import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function section(title, content) {
    return <div className={"demo-stack"}>
    {content}
    </div>;
}
function SavePair() {
    var name = React.useState(''), error = React.useState(''), message = React.useState('Измените название и сохраните объект.');
    function submit(e) {
        e.preventDefault();
        if (!name[0].trim()) {
            error[1]('Введите название объекта.');
            message[1]('Объект не сохранён. Исправьте поле названия.');
            e.currentTarget.querySelector('input').focus();
            return;
        }
        error[1]('');
        message[1]('Объект «' + name[0].trim() + '» сохранён.');
    }
    function cancel() { name[1](''); error[1](''); message[1]('Изменения отменены.'); }
    return section('Сохранение и отмена', <form className={'form'} noValidate={true} onSubmit={submit}>
    <S.DsField label={'Название объекта'} required={true} value={name[0]} error={error[0]} onChange={function (e) {
            name[1](e.target.value);
            if (error[0])
                error[1]('');
        }}/>
    <div className={'row actions'}>
    <S.DsButton tone={'secondary'} onClick={cancel}>
    {'Отмена'}
    </S.DsButton>
    <S.DsButton type={'submit'}>
    {'Сохранить'}
    </S.DsButton>
    </div>
    <p className={'cap'} role={'status'}>
    {message[0]}
    </p>
    </form>);
}
function App() {
    var timer = React.useRef();
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    return <div className="dsbutton-example">
    <style>{exampleStyles}</style>
    <SavePair />
    </div>;
}

const exampleStyles = ".dsbutton-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsbutton-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsbutton-example p{margin:0}\n.dsbutton-example .row{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.dsbutton-example .form{display:flex;flex-direction:column;gap:16px;max-width:360px}.dsbutton-example .actions{justify-content:flex-end}\n.dsbutton-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

